(function(root){
  const clone=v=>JSON.parse(JSON.stringify(v));
  const assert=(ok,message)=>{if(!ok)throw new Error(message);};
  function validLines(lines){assert(Array.isArray(lines)&&lines.length>0,'Add at least one service before finalizing.');for(const l of lines){assert(l.name&&l.name.trim(),'Every service needs a name.');assert(Number.isInteger(l.cents)&&l.cents>=0&&l.cents<=100000,'Service prices must be between $0 and $1,000.');assert(Number.isInteger(l.qty)&&l.qty>=1&&l.qty<=9,'Quantity must be from 1 to 9.');}}
  function subtotal(t){return t.lines.reduce((sum,l)=>sum+l.cents*l.qty,0);}
  function create(id,service){const list=Array.isArray(service)?service:[service];const lines=list.map((s,i)=>({id:'line-'+id+'-'+i,service:s.id,name:s.name,cents:Math.round(s.price*100),qty:1}));validLines(lines);return {id,revision:1,status:'draft',lines,original:clone(lines),snapshot:null,approval:null,note:'',history:[{event:'Ticket opened',revision:1,at:Date.now()}]};}
  function edit(t,lines){assert(t.status==='draft'||t.status==='changes_requested','Reopen this ticket before making changes. Approved tickets stay locked.');const next=clone(lines);if(next.length)validLines(next);t.lines=next;t.revision++;t.status='draft';t.snapshot=null;t.approval=null;t.history.push({event:'Services updated',revision:t.revision,at:Date.now()});return t;}
  function finalize(t){assert(t.status==='draft','Only an open ticket can be finalized.');validLines(t.lines);t.snapshot={revision:t.revision,lines:clone(t.lines),subtotalCents:subtotal(t)};t.status='finalized';t.history.push({event:'Ticket finalized',revision:t.revision,at:Date.now()});return t;}
  function send(t){assert(t.status==='finalized'&&t.snapshot?.revision===t.revision,'Finalize the current ticket before sending.');t.status='awaiting_approval';t.sentAt=Date.now();t.history.push({event:'Sent for client approval',revision:t.revision,at:Date.now()});return t;}
  function reopen(t){assert(['finalized','awaiting_approval','changes_requested'].includes(t.status),'This ticket cannot be reopened.');t.status='draft';t.revision++;t.snapshot=null;t.approval=null;t.history.push({event:'Reopened; prior approval request withdrawn',revision:t.revision,at:Date.now()});return t;}
  function requestChanges(t,note){assert(t.status==='awaiting_approval','Only a ticket awaiting approval can receive a change request.');assert(String(note).trim().length>=3,'Tell your barber what needs changing.');t.status='changes_requested';t.note=String(note).trim().slice(0,500);t.history.push({event:'Client requested changes',revision:t.revision,at:Date.now()});return t;}
  function approve(t,revision,tipCents){assert(t.status==='awaiting_approval','This ticket is no longer awaiting approval. Ask your barber to resend it.');assert(t.snapshot&&revision===t.revision&&revision===t.snapshot.revision,'The ticket changed. Review the latest services before approving.');assert(Number.isInteger(tipCents)&&tipCents>=0&&tipCents<=100000,'Choose no tip or enter a valid tip up to $1,000.');t.approval={revision,subtotalCents:t.snapshot.subtotalCents,tipCents,totalCents:t.snapshot.subtotalCents+tipCents,at:Date.now(),lines:clone(t.snapshot.lines)};t.status='approved';t.history.push({event:'Client approved services and tip',revision,at:Date.now()});return t;}
  const api={create,subtotal,validLines,edit,finalize,send,reopen,requestChanges,approve};
  if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.HFTickets=api;
})(typeof globalThis!=='undefined'?globalThis:this);
